def transform(grid):
    # What if square rectangles? None here.
    # What if it's based on hole orientation?
    # A hole with height > width is filled with 3, height < width is filled with 7.
    res = [row[:] for row in grid]
    for color in range(1, 10):
        coords = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
        if not coords: continue
        min_r, max_r = min(r for r,c in coords), max(r for r,c in coords)
        min_c, max_c = min(c for r,c in coords), max(c for r,c in coords)
        fill = 3 if (max_r - min_r) >= (max_c - min_c) else 7
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                if res[r][c] == 0:
                    res[r][c] = fill
    return res
